create schema if not exists ibp_private;
revoke all on schema ibp_private from public,anon,authenticated;
grant usage on schema ibp_private to service_role;

alter table public.plans add column if not exists ibp_enabled boolean not null default true;
alter table public.plans add column if not exists ibp_scenarios_enabled boolean not null default true;
alter table public.plans add column if not exists ibp_financial_reconciliation_enabled boolean not null default true;
alter table public.plans add column if not exists ibp_execution_bridge_enabled boolean not null default true;
alter table public.plans add column if not exists ibp_ai_copilot_enabled boolean not null default true;
alter table public.store_feature_flags add column if not exists ibp_enabled boolean not null default true;
alter table public.store_feature_flags add column if not exists ibp_scenarios_enabled boolean not null default true;
alter table public.store_feature_flags add column if not exists ibp_financial_reconciliation_enabled boolean not null default true;
alter table public.store_feature_flags add column if not exists ibp_execution_bridge_enabled boolean not null default true;
alter table public.store_feature_flags add column if not exists ibp_ai_copilot_enabled boolean not null default true;

create table public.ibp_member_permissions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,permissions text[] not null default '{}',scope_type text not null default 'organization' check(scope_type in('store','region','organization','network')),scope_ids uuid[] not null default '{}',active boolean not null default true,created_by uuid references auth.users(id),created_at timestamptz not null default now(),unique(organization_id,user_id));
create table public.ibp_planning_cycles(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,name text not null,cycle_type text not null check(cycle_type in('monthly_sop','weekly_tactical','quarterly_ibp','annual_plan','custom')),planning_context text not null default 'tenant_operational_ibp' check(planning_context in('tenant_operational_ibp','masterapp_internal_ibp')),horizon_start date not null,horizon_end date not null,bucket_granularity text not null check(bucket_granularity in('week','month')),status text not null default 'draft' check(status in('draft','demand_review','supply_review','financial_review','consensus','executive_review','approved','published','closed','cancelled')),current_version integer not null default 1,owner_user_id uuid references auth.users(id),confidentiality text not null default 'restricted' check(confidentiality in('standard','restricted','executive')),published_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(horizon_end>horizon_start),unique(organization_id,name,horizon_start));
create table public.ibp_plan_versions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,cycle_id uuid not null references public.ibp_planning_cycles(id) on delete cascade,version_number integer not null,status text not null default 'working' check(status in('working','submitted','approved','superseded')),based_on_version uuid references public.ibp_plan_versions(id),calculation_status text not null default 'queued' check(calculation_status in('queued','calculating','ready','failed')),lock_version integer not null default 1,created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),approved_at timestamptz,locked_at timestamptz,calculated_at timestamptz,calculation_error text,unique(cycle_id,version_number));
create table public.ibp_input_snapshots(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,plan_version_id uuid not null references public.ibp_plan_versions(id) on delete cascade,source_module text not null,source_version text not null,captured_at timestamptz not null,source_as_of timestamptz not null,payload_ref jsonb not null default '{}',content_hash text not null,data_quality text not null default 'complete' check(data_quality in('complete','partial','stale','missing')),unique(plan_version_id,source_module));
create table public.ibp_assumptions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,cycle_id uuid not null references public.ibp_planning_cycles(id) on delete cascade,plan_version_id uuid not null references public.ibp_plan_versions(id) on delete cascade,category text not null check(category in('demand','supply','price','labor','inflation','supplier','logistics','marketing','expansion','finance','custom')),title text not null,description text not null,scope jsonb not null,effective_period daterange not null,owner_user_id uuid references auth.users(id),status text not null default 'proposed' check(status in('proposed','accepted','rejected','superseded')),confidence text not null check(confidence in('high','medium','low')),evidence_refs jsonb not null default '[]',revision integer not null default 1,outcome text check(outcome in('confirmed','partially_true','not_realized','unknown')),created_at timestamptz not null default now());
create table public.ibp_demand_components(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,plan_version_id uuid not null references public.ibp_plan_versions(id) on delete cascade,period_start date not null,scope_key text not null,component_type text not null check(component_type in('statistical_forecast','commercial_override','promotion_uplift','new_store','store_closure','seasonality','event','price_change','known_contract','manual_adjustment')),value numeric not null,unit text not null,source_ref jsonb not null,composition_rule text not null default 'delta',promotion_in_source_forecast boolean not null default false,created_at timestamptz not null default now());
create table public.ibp_demand_adjustments(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,plan_version_id uuid not null references public.ibp_plan_versions(id) on delete cascade,scope jsonb not null,period_start date not null,adjustment_type text not null check(adjustment_type in('absolute','percentage','replace')),value numeric not null,reason text not null,author_user_id uuid not null references auth.users(id),evidence_refs jsonb not null default '[]',lock_version integer not null default 1,created_at timestamptz not null default now());
create table public.ibp_supply_gaps(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,plan_version_id uuid not null references public.ibp_plan_versions(id) on delete cascade,period_start date not null,scope jsonb not null,demand numeric not null,feasible_supply numeric not null,gap numeric generated always as (demand-feasible_supply) stored,constraint_type text not null check(constraint_type in('supplier','material','production','inventory','transport','capacity','quality','lead_time','budget','unknown')),source_ref jsonb not null,severity text not null check(severity in('low','medium','high','critical')),status text not null default 'open' check(status in('open','reviewed','accepted','resolved')),unique(plan_version_id,period_start,scope,constraint_type));
create table public.ibp_constraints(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,plan_version_id uuid not null references public.ibp_plan_versions(id) on delete cascade,constraint_type text not null,title text not null,scope jsonb not null,period_start date,severity text not null,options jsonb not null default '[]',selected_option jsonb,decision_ref uuid,owner_user_id uuid references auth.users(id),due_at timestamptz,status text not null default 'open',accepted_risk_reason text,created_at timestamptz not null default now());
create table public.ibp_scenarios(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,cycle_id uuid not null references public.ibp_planning_cycles(id) on delete cascade,name text not null,scenario_type text not null check(scenario_type in('base','upside','downside','constrained','custom')),based_on_version uuid not null references public.ibp_plan_versions(id),status text not null default 'draft' check(status in('draft','calculating','ready','archived')),deltas jsonb not null default '[]',result_summary jsonb not null default '{}',created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),unique(cycle_id,name));
create table public.ibp_plan_cube(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,cycle_id uuid not null references public.ibp_planning_cycles(id) on delete cascade,plan_version_id uuid not null references public.ibp_plan_versions(id) on delete cascade,scenario_id uuid references public.ibp_scenarios(id) on delete cascade,period_start date not null,scope_key text not null,grain jsonb not null,demand numeric,supply numeric,capacity_required numeric,capacity_available numeric,revenue numeric,contribution_margin numeric,inventory numeric,budget numeric,target numeric,actual numeric,lineage jsonb not null default '[]',calculated_at timestamptz not null default now(),unique(plan_version_id,scenario_id,period_start,scope_key));
create table public.ibp_stage_reviews(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,plan_version_id uuid not null references public.ibp_plan_versions(id) on delete cascade,stage text not null check(stage in('demand_review','supply_review','capacity_review','financial_review','consensus','executive_review')),status text not null default 'pending' check(status in('pending','in_review','completed','overridden')),requirements jsonb not null default '{}',participants jsonb not null default '[]',completed_by uuid references auth.users(id),completed_at timestamptz,override_reason text,unique(plan_version_id,stage));
create table public.ibp_approvals(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,plan_version_id uuid not null references public.ibp_plan_versions(id) on delete cascade,approval_ref uuid,status text not null default 'pending' check(status in('pending','approved','rejected','cancelled')),decision text,reason text,decided_by uuid references auth.users(id),decided_at timestamptz,created_at timestamptz not null default now());
create table public.ibp_plan_amendments(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,original_version_id uuid not null references public.ibp_plan_versions(id),derived_version_id uuid not null references public.ibp_plan_versions(id),reason text not null,impact jsonb not null,effective_period daterange not null,approved_by uuid references auth.users(id),created_at timestamptz not null default now(),unique(original_version_id,derived_version_id));
create table public.ibp_execution_targets(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,plan_version_id uuid not null references public.ibp_plan_versions(id) on delete cascade,target_type text not null check(target_type in('demand_target','inventory_target','purchase_requirement','production_requirement','capacity_requirement','labor_requirement','transport_requirement','marketing_spend','financial_forecast')),scope jsonb not null,period_start date not null,target_value numeric not null,source_metric text not null,destination_module text not null,status text not null default 'proposed' check(status in('proposed','published','consumed','superseded')),consumption_ref jsonb,created_at timestamptz not null default now());
create table public.ibp_variances(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,plan_version_id uuid not null references public.ibp_plan_versions(id) on delete cascade,period_start date not null,scope_key text not null,metric_key text not null,plan_value numeric,actual_value numeric,variance numeric,variance_percent numeric,drivers jsonb not null default '[]',driver_quality text not null default 'unavailable',calculated_at timestamptz not null default now(),unique(plan_version_id,period_start,scope_key,metric_key));
create table public.ibp_cycle_calendars(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,cycle_id uuid not null references public.ibp_planning_cycles(id) on delete cascade,stage text not null,due_at timestamptz not null,owner_user_id uuid references auth.users(id),reviewer_user_ids uuid[] not null default '{}',approver_user_ids uuid[] not null default '{}',status text not null default 'scheduled',unique(cycle_id,stage));
create table public.ibp_comments(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,plan_version_id uuid not null references public.ibp_plan_versions(id) on delete cascade,context_type text not null check(context_type in('cell','period','assumption','constraint')),context_ref text not null,body text not null,author_user_id uuid not null references auth.users(id),created_at timestamptz not null default now());
create table public.ibp_audit_events(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,actor_user_id uuid references auth.users(id),action text not null,entity_type text not null,entity_id uuid,reason text,before_state jsonb,after_state jsonb,created_at timestamptz not null default now());

-- quality: allow-nonconcurrent-index reason=new-empty-ibp-tables
create index ibp_cycles_status_idx on public.ibp_planning_cycles(organization_id,status,horizon_start);
create index ibp_versions_cycle_idx on public.ibp_plan_versions(cycle_id,version_number desc);
create index ibp_cube_slice_idx on public.ibp_plan_cube(plan_version_id,period_start,scope_key);
create index ibp_gaps_open_idx on public.ibp_supply_gaps(organization_id,severity,status) where status in('open','reviewed');
create index ibp_targets_status_idx on public.ibp_execution_targets(organization_id,destination_module,status);

create or replace function ibp_private.org_allowed(org uuid,permission_name text default 'ibp:view') returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.organization_members m where m.organization_id=org and m.user_id=(select auth.uid()) and m.active and (m.role in('owner','admin','manager','supervisor') or exists(select 1 from public.ibp_member_permissions p where p.organization_id=org and p.user_id=(select auth.uid()) and p.active and permission_name=any(p.permissions))))$$;
revoke all on function ibp_private.org_allowed(uuid,text) from public,anon;
grant execute on function ibp_private.org_allowed(uuid,text) to authenticated;
do $$declare t text;begin foreach t in array array['ibp_member_permissions','ibp_planning_cycles','ibp_plan_versions','ibp_input_snapshots','ibp_assumptions','ibp_demand_components','ibp_demand_adjustments','ibp_supply_gaps','ibp_constraints','ibp_scenarios','ibp_plan_cube','ibp_stage_reviews','ibp_approvals','ibp_plan_amendments','ibp_execution_targets','ibp_variances','ibp_cycle_calendars','ibp_comments','ibp_audit_events'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;end$$;
create policy ibp_cycles_read on public.ibp_planning_cycles for select to authenticated using((select ibp_private.org_allowed(organization_id,'ibp:view')));
create policy ibp_versions_read on public.ibp_plan_versions for select to authenticated using((select ibp_private.org_allowed(organization_id,'ibp:view')));
create policy ibp_snapshots_read on public.ibp_input_snapshots for select to authenticated using((select ibp_private.org_allowed(organization_id,'ibp:view')));
create policy ibp_assumptions_read on public.ibp_assumptions for select to authenticated using((select ibp_private.org_allowed(organization_id,'ibp:view')));
create policy ibp_cube_read on public.ibp_plan_cube for select to authenticated using((select ibp_private.org_allowed(organization_id,'ibp:view')));
create policy ibp_gaps_read on public.ibp_supply_gaps for select to authenticated using((select ibp_private.org_allowed(organization_id,'ibp:view')));
create policy ibp_constraints_read on public.ibp_constraints for select to authenticated using((select ibp_private.org_allowed(organization_id,'ibp:view')));
create policy ibp_scenarios_read on public.ibp_scenarios for select to authenticated using((select ibp_private.org_allowed(organization_id,'ibp:view')));
create policy ibp_targets_read on public.ibp_execution_targets for select to authenticated using((select ibp_private.org_allowed(organization_id,'ibp:view')));
create policy ibp_variances_read on public.ibp_variances for select to authenticated using((select ibp_private.org_allowed(organization_id,'ibp:view')));

insert into public.analytics_metric_catalog(metric_key,name,description,formula,source_of_truth,grain,owner_label,refresh_frequency,unit,evidence_class,certified,sensitive,allowed_dimensions) values
('ibp_consensus_demand','Consensus Demand','Demanda consensada da versão publicada.','sum(demand) for published plan version','ibp_plan_cube','scope/period','Planejamento','per_cycle','number','calculation',true,false,array['organization','brand','region','store','channel','category']),
('ibp_constrained_supply','Constrained Supply Plan','Oferta viável após restrições explícitas.','sum(supply) for published plan version','ibp_plan_cube','scope/period','Supply Chain','per_cycle','number','calculation',true,false,array['organization','brand','region','store','channel','category']),
('ibp_planned_revenue','Planned Revenue','Receita do plano, separada de budget, target, forecast e actual.','sum(revenue) for published plan version','ibp_plan_cube','scope/period','Financeiro','per_cycle','BRL','calculation',true,true,array['organization','brand','region','store','channel','category'])
on conflict(metric_key) do update set description=excluded.description,formula=excluded.formula,source_of_truth=excluded.source_of_truth,grain=excluded.grain,owner_label=excluded.owner_label,refresh_frequency=excluded.refresh_frequency,unit=excluded.unit,evidence_class=excluded.evidence_class,certified=excluded.certified,sensitive=excluded.sensitive,allowed_dimensions=excluded.allowed_dimensions,updated_at=now();
